function drawMapMarker(p,marker,size,color){const s=Math.max(2,size),style=markerType(marker);ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle=color;ctx.strokeStyle=colorWithAlpha(color,.96);ctx.lineWidth=Math.max(.7,s*.18);ctx.setLineDash([]);if(style==='home'){ctx.beginPath();ctx.moveTo(-s,-s*.08);ctx.lineTo(0,-s);ctx.lineTo(s,-s*.08);ctx.lineTo(s,s*.8);ctx.lineTo(-s,s*.8);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#071017';ctx.fillRect(-s*.2,s*.25,s*.4,s*.55)}else if(style==='station'){ctx.beginPath();for(let i=0;i<6;i++){const angle=-Math.PI/2+i*Math.PI/3,x=Math.cos(angle)*s,y=Math.sin(angle)*s;i?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#071017';ctx.beginPath();ctx.arc(0,0,s*.3,0,Math.PI*2);ctx.fill()}else if(style==='asteroid'){ctx.beginPath();[[-.95,-.22],[-.48,-.92],[.48,-.73],[.98,-.12],[.62,.77],[-.2,.98],[-.88,.48]].forEach(([x,y],index)=>index?ctx.lineTo(x*s,y*s):ctx.moveTo(x*s,y*s));ctx.closePath();ctx.fill();ctx.stroke()}else if(style==='danger'){ctx.beginPath();ctx.moveTo(0,-s);ctx.lineTo(s*.95,s*.82);ctx.lineTo(-s*.95,s*.82);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#071017';ctx.fillRect(-s*.12,-s*.4,s*.24,s*.62);ctx.beginPath();ctx.arc(0,s*.48,s*.15,0,Math.PI*2);ctx.fill()}else{ctx.beginPath();ctx.arc(0,0,s,0,Math.PI*2);ctx.fill()}ctx.restore()}
