function drawRegion(region,active=false){const color=regionColor(region),segments=active?48:32,points=[];for(let i=0;i<=segments;i++){const angle=(i/segments)*Math.PI*2;points.push(project(region.center.x+Math.cos(angle)*region.r,region.center.y,region.center.z+Math.sin(angle)*region.r))}ctx.save();ctx.strokeStyle=colorWithAlpha(color,active ? .42 : .14);ctx.lineWidth=active?1.3:1;ctx.setLineDash(active?[7,6]:[3,9]);ctx.beginPath();points.forEach((p,index)=>index?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();ctx.restore()}
function drawOverviewRegion(region,active=false){const p=project(region.center.x,region.center.y,region.center.z),cue=depthCue(p),color=regionColor(region),count=regionClusters(region).length;if(p.x<-50||p.x>canvas.clientWidth+50||p.y<-50||p.y>canvas.clientHeight+50)return;ctx.save();ctx.globalAlpha=active?1:cue.alpha;ctx.shadowColor=color;ctx.shadowBlur=(active?34:22)*cue.scale;ctx.fillStyle=color;ctx.beginPath();ctx.arc(p.x,p.y,(active?9:7)*cue.scale,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.lineWidth=(active?1.5:1)*cue.scale;ctx.strokeStyle=colorWithAlpha(color,active ? .96 : .72);ctx.setLineDash([]);ctx.beginPath();ctx.arc(p.x,p.y,(active?24:18)*cue.scale,0,Math.PI*2);ctx.stroke();ctx.font=`${Math.round(9+cue.scale*2)}px DM Mono`;const lines=[regionLabel(region).toUpperCase(),count+' '+(count===1?'CLUSTER':'CLUSTERS')],labelWidth=Math.max(...lines.map(line=>ctx.measureText(line).width))+10,labelHeight=32,placements=[{dx:17,dy:-25},{dx:-labelWidth-17,dy:-25},{dx:17,dy:16},{dx:-labelWidth-17,dy:16},{dx:17,dy:-58},{dx:-labelWidth-17,dy:-58}];let box=null;for(const placement of placements){const candidate={x:p.x+placement.dx,y:p.y+placement.dy,w:labelWidth,h:labelHeight};if(candidate.x<8||candidate.x+candidate.w>canvas.clientWidth-8||candidate.y<8||candidate.y+candidate.h>canvas.clientHeight-8)continue;if(!labelBoxes.some(other=>candidate.x<other.x+other.w&&candidate.x+candidate.w>other.x&&candidate.y<other.y+other.h&&candidate.y+candidate.h>other.y)){box=candidate;break}}if(box){labelBoxes.push(box);ctx.shadowColor='#071017';ctx.shadowBlur=4;ctx.fillStyle=color;ctx.fillText(lines[0],box.x+4,box.y+11);ctx.fillStyle='rgba(220,235,231,.78)';ctx.fillText(lines[1],box.x+4,box.y+24);ctx.shadowBlur=0;ctx.strokeStyle=colorWithAlpha(color,.38);ctx.setLineDash([2,3]);ctx.beginPath();ctx.moveTo(p.x+(box.x>p.x?5:-5),p.y);ctx.lineTo(box.x>p.x?box.x-2:box.x+box.w+2,box.y+15);ctx.stroke()}ctx.restore()}
function drawOverviewSector(cluster,active=false){const p=project(cluster.x,cluster.y,cluster.z),cue=depthCue(p),color=clusterColor(cluster),members=clusterNodes(cluster),names=members.map(node=>node.name).filter((name,index,all)=>all.indexOf(name)===index).slice(0,4);if(p.x<-50||p.x>canvas.clientWidth+50||p.y<-50||p.y>canvas.clientHeight+50)return;ctx.save();ctx.globalAlpha=active?1:cue.alpha;ctx.shadowColor=color;ctx.shadowBlur=(active?30:18)*cue.scale;ctx.fillStyle=color;ctx.beginPath();ctx.arc(p.x,p.y,(active?7:5)*cue.scale,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.lineWidth=(active?1.5:1)*cue.scale;ctx.strokeStyle=colorWithAlpha(color,active ? .96 : .58);ctx.setLineDash([]);ctx.beginPath();ctx.arc(p.x,p.y,(active?17:12)*cue.scale,0,Math.PI*2);ctx.stroke();ctx.font=`${Math.round(9+cue.scale*2)}px DM Mono`;const lines=[clusterLabel(cluster),...names],labelWidth=Math.max(...lines.map(line=>ctx.measureText(line).width))+10,labelHeight=lines.length*13+6,placements=[{dx:12,dy:-14},{dx:-labelWidth-12,dy:-14},{dx:12,dy:-labelHeight-12},{dx:-labelWidth-12,dy:-labelHeight-12},{dx:12,dy:16},{dx:-labelWidth-12,dy:16},{dx:12,dy:-labelHeight-32},{dx:-labelWidth-12,dy:-labelHeight-32},{dx:12,dy:36},{dx:-labelWidth-12,dy:36}];let box=null;for(const placement of placements){const candidate={x:p.x+placement.dx,y:p.y+placement.dy-8,w:labelWidth,h:labelHeight};if(candidate.x<8||candidate.x+candidate.w>canvas.clientWidth-8||candidate.y<8||candidate.y+candidate.h>canvas.clientHeight-8)continue;if(!labelBoxes.some(other=>candidate.x<other.x+other.w&&candidate.x+candidate.w>other.x&&candidate.y<other.y+other.h&&candidate.y+candidate.h>other.y)){box=candidate;break}}if(box){labelBoxes.push(box);ctx.shadowColor='#071017';ctx.shadowBlur=4;lines.forEach((line,index)=>{ctx.fillStyle=index?'rgba(220,235,231,.88)':color;ctx.fillText(line,box.x+4,box.y+11+index*13)});ctx.shadowBlur=0;ctx.strokeStyle=colorWithAlpha(color,.35);ctx.setLineDash([2,3]);ctx.beginPath();ctx.moveTo(p.x+(box.x>p.x?4:-4),p.y);ctx.lineTo(box.x>p.x?box.x-2:box.x+box.w+2,box.y+Math.min(10,box.h/2));ctx.stroke()}ctx.restore()}
function drawNode(n){const p=n.p,cue=depthCue(p),is=selected&&selected.id===n.id,hover=hoveredNode&&hoveredNode.id===n.id,active=is||hover,color=nodeColor(n);ctx.save();ctx.globalAlpha=active?1:cue.alpha;ctx.shadowBlur=(active?24:13)*cue.scale;ctx.shadowColor=color;ctx.fillStyle=hover&&!is?'#f2ffed':color;ctx.beginPath();ctx.arc(p.x,p.y,(is?6:hover?5:4)*cue.scale,0,Math.PI*2);ctx.fill();if(active){ctx.shadowBlur=0;ctx.lineWidth=(hover&&!is?1.5:1)*cue.scale;ctx.strokeStyle=color;ctx.setLineDash([2,4]);ctx.beginPath();ctx.arc(p.x,p.y,(hover&&!is?17:15)*cue.scale,0,Math.PI*2);ctx.stroke()}if(!n.showLabel&&!active){ctx.restore();return}ctx.shadowColor='#071017';ctx.shadowBlur=4;ctx.font=`${Math.round(10+cue.scale*1.5)}px DM Mono`;const labelWidth=ctx.measureText(n.name).width+4,labelHeight=15,offsets=[0,-18,18,-36,36,-54,54];let labelX=p.x+9,labelY=p.y-8;for(let i=0;i<offsets.length;i++){const candidate={x:p.x+9,y:p.y-8+offsets[i],w:labelWidth,h:labelHeight};if(candidate.y<12||candidate.y>canvas.clientHeight-8)continue;if(!labelBoxes.some(box=>candidate.x<box.x+box.w&&candidate.x+candidate.w>box.x&&candidate.y<box.y+box.h&&candidate.y+candidate.h>box.y)){labelX=candidate.x;labelY=candidate.y;labelBoxes.push(candidate);break}}if(Math.abs(labelX-(p.x+9))>4||Math.abs(labelY-(p.y-8))>4){ctx.shadowBlur=0;ctx.strokeStyle='rgba(220,235,231,.35)';ctx.setLineDash([2,3]);ctx.beginPath();ctx.moveTo(p.x+5,p.y);ctx.lineTo(labelX-2,labelY+5);ctx.stroke()}ctx.shadowColor='#071017';ctx.shadowBlur=4;ctx.fillStyle=is?'#e7f5da':hover?'#effffe':'rgba(220,235,231,.88)';ctx.fillText(n.name,labelX,labelY);ctx.restore()}
function drawCurrentPosition(){if(!currentPosition)return;const p=project(...Object.values(world(currentPosition)));if(p.x<-45||p.x>canvas.clientWidth+45||p.y<-45||p.y>canvas.clientHeight+45)return;ctx.save();ctx.shadowColor='#f08bd2';ctx.shadowBlur=25;ctx.fillStyle='#f08bd2';ctx.beginPath();ctx.moveTo(p.x,p.y-8);ctx.lineTo(p.x+8,p.y);ctx.lineTo(p.x,p.y+8);ctx.lineTo(p.x-8,p.y);ctx.closePath();ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='rgba(255,207,240,.92)';ctx.setLineDash([2,3]);ctx.beginPath();ctx.arc(p.x,p.y,18,0,Math.PI*2);ctx.stroke();ctx.font='10px DM Mono';ctx.fillStyle='#ffe0f3';ctx.shadowColor='#071017';ctx.shadowBlur=4;ctx.fillText('CURRENT · '+currentPosition.name,p.x+12,p.y-12);ctx.restore()}
function niceDistance(value){const magnitude=10**Math.floor(Math.log10(value||1)),unit=value/magnitude;return(unit>=5?5:unit>=2?2:1)*magnitude}
function updateScale(){const worldWidth=canvas.clientWidth/(Math.min(canvas.clientWidth,canvas.clientHeight)/(projectionExtent*2));const distance=niceDistance(worldWidth/(5*zoom));document.getElementById('mapScale').textContent=(distance>=1000?(distance/1000).toLocaleString()+' M km':distance.toLocaleString()+' km')}
function formatDistance(value){return value>=1000?(value/1000).toLocaleString(undefined,{maximumFractionDigits:1})+'M km':Math.round(value).toLocaleString()+' km'}
function updateMapMode(){const sector=focusedCluster;if(sector){document.getElementById('mapEyebrow').textContent=`${focusedRegion?.kind?.toUpperCase()||'UNASSIGNED'} / SECTOR`;document.getElementById('mapTitle').textContent=`${overviewMode==='clusters'?'All clusters':focusedRegion?regionLabel(focusedRegion):'Unassigned'} · ${clusterLabel(sector)}`;document.getElementById('mapHint').textContent='Select a GPS signal to inspect it · Use the return button to go back';document.getElementById('visibleLabel').textContent='GPS SIGNALS'}else if(focusedRegion){document.getElementById('mapEyebrow').textContent=`${focusedRegion.kind.toUpperCase()} OVERVIEW`;document.getElementById('mapTitle').textContent=regionLabel(focusedRegion);document.getElementById('mapHint').textContent='Select a cluster to inspect its GPS signals';document.getElementById('visibleLabel').textContent='VISIBLE CLUSTERS'}else if(overviewMode==='clusters'){document.getElementById('mapEyebrow').textContent='CLUSTER OVERVIEW';document.getElementById('mapTitle').textContent='All clusters';document.getElementById('mapHint').textContent='Select a cluster to inspect its GPS signals';document.getElementById('visibleLabel').textContent='VISIBLE CLUSTERS'}else{document.getElementById('mapEyebrow').textContent='REGION OVERVIEW';document.getElementById('mapTitle').textContent='Known space';document.getElementById('mapHint').textContent='Select a region to inspect its clusters';document.getElementById('visibleLabel').textContent='VISIBLE REGIONS'}overviewToggle.textContent=overviewMode==='regions'?'◈ All clusters':'◌ Region view'}
function draw(){refreshProjection();updateViewCube();const w=canvas.clientWidth,h=canvas.clientHeight;ctx.clearRect(0,0,w,h);labelBoxes.length=0;const grad=ctx.createRadialGradient(w*.54,h*.48,0,w*.54,h*.48,w*.72);grad.addColorStop(0,'#183d42');grad.addColorStop(.48,'#0c2029');grad.addColorStop(1,'#071017');ctx.fillStyle=grad;ctx.fillRect(0,0,w,h);stars(w,h);drawAxisPlanes();let displayCount=0;if(focusedCluster){drawCluster(focusedCluster);const labelsShown={};const display=mapDisplayNodes().map(n=>({...n,p:project(...Object.values(world(n)))})).sort((a,b)=>b.p.depth-a.p.depth);display.forEach(n=>{const sector=n.cluster||'Unassigned',show=(labelsShown[sector]||0)<4;if(show)labelsShown[sector]=(labelsShown[sector]||0)+1;drawNode({...n,showLabel:show})});displayCount=display.length}else if(focusedRegion){drawRegion(focusedRegion,true);const sectors=regionClusters(focusedRegion).slice().sort((a,b)=>project(b.x,b.y,b.z).depth-project(a.x,a.y,a.z).depth);sectors.forEach(cluster=>drawOverviewSector(cluster,hoveredCluster?.name===cluster.name));displayCount=sectors.length}else if(overviewMode==='clusters'){const sectors=clusters.filter(cluster=>clusterNodes(cluster).length).sort((a,b)=>project(b.x,b.y,b.z).depth-project(a.x,a.y,a.z).depth);sectors.forEach(cluster=>drawOverviewSector(cluster,hoveredCluster?.name===cluster.name));displayCount=sectors.length}else{const regionList=overviewRegions().slice().sort((a,b)=>project(b.center.x,b.center.y,b.center.z).depth-project(a.center.x,a.center.y,a.center.z).depth);regionList.forEach(region=>drawRegion(region));regionList.forEach(region=>drawOverviewRegion(region,hoveredRegion?.key===region.key));displayCount=regionList.length}drawCurrentPosition();document.getElementById('visibleNodes').textContent=String(displayCount).padStart(2,'0');document.getElementById('clusterCount').textContent=String(clusters.length).padStart(2,'0');document.getElementById('mapSpan').textContent=formatDistance(projectionExtent*2);updateMapMode();updateScale()}
function renderList(){invalidateVisible();const list=document.getElementById('locationList');list.innerHTML=visible().map(n=>{const info=categoryInfo(n.type),detail=n.ore&&n.ore!=='—'&&n.ore!=='Unknown'?n.ore:info.label;return`<article class="location-item ${selected&&selected.id===n.id?'selected':''}" data-id="${n.id}"><span class="tag" style="color:${nodeColor(n)}">${info.tag}</span><h3>${n.name}</h3><p>${detail} · ${n.cluster}</p></article>`}).join('');list.onwheel=e=>{if(list.scrollHeight>list.clientHeight){list.scrollTop+=e.deltaY;e.preventDefault()}};list.querySelectorAll('.location-item').forEach(el=>el.onclick=()=>{const n=nodes.find(item=>item.id===+el.dataset.id),sector=clusters.find(cluster=>cluster.name===n?.cluster);if(sector&&!focusedCluster)focusSector(sector.name);select(+el.dataset.id)});document.getElementById('entryCount').textContent=String(nodes.length).padStart(2,'0');document.getElementById('allCount').textContent=nodes.length;categories.forEach(type=>{const count=document.getElementById(type+'Count');if(count)count.textContent=nodes.filter(n=>normalizeCategory(n.type,n.ore)===type).length});renderFavorites()}
function gpsString(n){const color='#FF'+nodeColor(n).slice(1);return`GPS:${n.name}:${n.x}:${n.y}:${n.z}:${color}:${n.note||''}:`}
async function copyGps(n){const text=gpsString(n),button=document.getElementById('copySelected');try{await navigator.clipboard.writeText(text)}catch{const field=document.createElement('textarea');field.value=text;field.style.position='fixed';field.style.opacity='0';document.body.appendChild(field);field.select();document.execCommand('copy');field.remove()}button.textContent='✓ GPS copied';button.classList.add('copied');setTimeout(()=>{if(document.getElementById('copySelected')===button){button.textContent='⧉ Copy GPS';button.classList.remove('copied')}},1600)}
function select(id){selected=nodes.find(n=>n.id===id);const n=selected,info=categoryInfo(n.type),color=nodeColor(n),measurement=measureOrigin&&measureOrigin.id!==n.id?Math.hypot(n.x-measureOrigin.x,n.y-measureOrigin.y,n.z-measureOrigin.z)/1000:null;document.getElementById('selectedCard').innerHTML=`<div class="node-head"><div><h2>${n.name}</h2><span class="node-type" style="color:${color}">${info.detail}${n.ore&&n.ore!=='—'&&n.ore!=='Unknown'?' · '+n.ore:''}</span></div><span class="node-id">#${String(n.id).padStart(3,'0')}</span></div><div class="description-block"><span>DESCRIPTION</span><p>${n.note||'No description added yet.'}</p></div>${measurement===null?'':`<div class="measurement-card">DISTANCE FROM ${measureOrigin.name.toUpperCase()}<strong>${measurement.toLocaleString(undefined,{maximumFractionDigits:2})} km</strong></div>`}<div class="selected-actions"><button class="copy-btn" id="copySelected">⧉ Copy GPS</button><button class="measure-btn" id="measureSelected">⌖ Measure</button><button class="favorite-btn ${isFavorite(n)?'active':''}" id="favoriteSelected">${isFavorite(n)?'★ Favorited':'☆ Favorite'}</button></div><button class="add-btn" id="editSelected" style="width:100%;margin-top:8px">✎ Edit GPS marker</button><button class="delete-btn" id="deleteSelected" style="width:100%;margin-top:8px;padding:9px;border:1px solid #744b48;background:#25191a;color:#f29a88;border-radius:3px;font:10px var(--mono);cursor:pointer">⌫ Delete GPS marker</button>`;document.getElementById('copySelected').onclick=()=>copyGps(n);document.getElementById('measureSelected').onclick=()=>{measureOrigin=n;select(n.id)};document.getElementById('favoriteSelected').onclick=()=>{toggleFavorite(n);select(n.id)};document.getElementById('editSelected').onclick=()=>openEdit(n);document.getElementById('deleteSelected').onclick=()=>deleteSelected(n.id);renderList();draw()}
function openEdit(n){document.getElementById('editGps').value=gpsString(n);document.getElementById('editType').value=normalizeCategory(n.type,n.ore);document.getElementById('editColor').value=nodeColor(n);document.getElementById('editDescription').value=n.note==='Imported from MySQL.'?'':n.note;document.getElementById('editVisibility').value=n.visibility||'user';document.getElementById('editError').textContent='';document.getElementById('editModal').classList.remove('hidden')}
document.getElementById('closeEditModal').onclick=()=>document.getElementById('editModal').classList.add('hidden');document.getElementById('editForm').onsubmit=async e=>{e.preventDefault();if(!selected)return;const f=new FormData(e.target),gps=parseGps(f.get('gps')),error=document.getElementById('editError');if(!gps){error.textContent='GPS format not recognized. Use GPS:Name:X:Y:Z:#COLOR:Description:';return}const type=normalizeCategory(f.get('type'),selected.ore),color=safeColor(f.get('color'),nodeColor(selected)),visibility=f.get('visibility')||selected.visibility||'user',updated={name:gps.name,type,x:gps.x,y:gps.y,z:gps.z,ore:type==='asteroid'?(selected.ore||'Unknown'):'—',note:f.get('description')||gps.description||'Edited GPS entry.',visibility,color};try{if(document.getElementById('datasetStatus').textContent==='MYSQL CONNECTED'){const response=await fetch('http://127.0.0.1:8765/api/update',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:selected.id,name:updated.name,x:updated.x,y:updated.y,z:updated.z,location_type:updated.type,description:updated.note,visibility})});const result=await response.json();if(!response.ok||result.error)throw new Error(result.error||'Could not save to MySQL')}else await saveEntityVisibility('gps',selected.id,visibility);gpsColorSettings[String(selected.id)]={color};if(!saveGpsColorSettings())throw new Error('Your browser could not save the GPS color.');Object.assign(selected,updated);document.getElementById('editModal').classList.add('hidden');select(selected.id)}catch(err){error.textContent=err.message}};
const regionModal=document.getElementById('regionModal');function openRegionEditor(region){editingRegion=region;document.getElementById('regionName').value=region.name;document.getElementById('regionColor').value=regionColor(region);document.getElementById('regionDescription').value=region.description||'';document.getElementById('regionVisibility').value=region.visibility||'user';document.getElementById('regionError').textContent='';regionModal.classList.remove('hidden');document.getElementById('regionName').focus()}document.getElementById('closeRegionModal').onclick=()=>regionModal.classList.add('hidden');document.getElementById('regionForm').onsubmit=async e=>{e.preventDefault();if(!editingRegion)return;const form=new FormData(e.target),name=String(form.get('name')||'').trim(),color=safeColor(form.get('color'),regionColor(editingRegion)),description=String(form.get('description')||'').trim(),visibility=form.get('visibility')||'user',error=document.getElementById('regionError');if(!name){error.textContent='Region name is required.';return}try{await saveEntityVisibility('region',editingRegion.key,visibility)}catch(err){error.textContent=err.message;return}regionSettings[editingRegion.key]={name,description,color};if(!saveRegionSettings()){error.textContent='Your browser could not save region details.';return}editingRegion.name=name;editingRegion.description=description;editingRegion.color=color;editingRegion.visibility=visibility;editingRegion.clusters.forEach(cluster=>cluster.region=name);regionModal.classList.add('hidden');renderSectors();renderRegionDetails(editingRegion);if(focusedCluster)document.getElementById('backToMap').textContent=`← ${regionLabel(editingRegion)}`;draw()};
const clusterModal=document.getElementById('clusterModal');function openClusterEditor(cluster){editingCluster=cluster;document.getElementById('clusterName').value=clusterLabel(cluster);document.getElementById('clusterColor').value=clusterColor(cluster);document.getElementById('clusterDescription').value=cluster.description||'';document.getElementById('clusterVisibility').value=cluster.visibility||'user';document.getElementById('clusterError').textContent='';clusterModal.classList.remove('hidden');document.getElementById('clusterName').focus()}document.getElementById('closeClusterModal').onclick=()=>clusterModal.classList.add('hidden');document.getElementById('clusterForm').onsubmit=async e=>{e.preventDefault();if(!editingCluster)return;const form=new FormData(e.target),name=String(form.get('name')||'').trim(),color=safeColor(form.get('color'),clusterColor(editingCluster)),description=String(form.get('description')||'').trim(),visibility=form.get('visibility')||'user',error=document.getElementById('clusterError');if(!name){error.textContent='Cluster name is required.';return}try{await saveEntityVisibility('cluster',editingCluster.name,visibility)}catch(err){error.textContent=err.message;return}clusterSettings[editingCluster.name]={name,description,color};if(!saveClusterSettings()){error.textContent='Your browser could not save cluster details.';return}editingCluster.displayName=name;editingCluster.description=description;editingCluster.color=color;editingCluster.visibility=visibility;clusterModal.classList.add('hidden');renderSectors();renderClusterDetails(editingCluster);draw()};
function deleteSelected(id){const n=nodes.find(item=>item.id===id);if(!n)return;if(!window.confirm(`Delete GPS marker “${n.name}”?`))return;const index=nodes.findIndex(item=>item.id===id);nodes.splice(index,1);favoriteIds.delete(String(id));saveFavorites();if(measureOrigin&&measureOrigin.id===id)measureOrigin=null;selected=null;document.getElementById('selectedCard').innerHTML='<div class="empty-state"><span>◎</span><strong>Select a node</strong><p>Choose a location from the atlas or map to inspect its coordinates.</p></div>';renderList();draw()}
function parseGps(text){const parts=text.trim().split(':');if(parts.length<6||parts[0].toUpperCase()!=='GPS')return null;const x=Number(parts[2]),y=Number(parts[3]),z=Number(parts[4]);if(!parts[1]||![x,y,z].every(Number.isFinite))return null;return{name:parts[1],x,y,z,description:parts.slice(6).join(':').trim()}}
document.getElementById('search').oninput=e=>{query=e.target.value.toLowerCase();renderList();draw()};document.querySelectorAll('.filter').forEach(b=>b.onclick=()=>{document.querySelectorAll('.filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');filter=b.dataset.filter;renderList();draw()});
const mapTooltip=document.getElementById('mapTooltip');
