function openEdit(n){document.getElementById('editGps').value=gpsString(n);document.getElementById('editType').value=normalizeCategory(n.type,n.ore);document.getElementById('editColor').value=nodeColor(n);document.getElementById('editMarker').value=nodeMarker(n);document.getElementById('editDescription').value=n.note==='Imported from MySQL.'?'':n.note;document.getElementById('editVisibility').value=n.visibility||'user';document.getElementById('editError').textContent='';document.getElementById('editModal').classList.remove('hidden')}
document.getElementById('editForm').onsubmit=async e=>{e.preventDefault();if(!selected)return;const f=new FormData(e.target),gps=parseGps(f.get('gps')),error=document.getElementById('editError');if(!gps){error.textContent='GPS format not recognized. Use GPS:Name:X:Y:Z:#COLOR:Description:';return}const type=normalizeCategory(f.get('type'),selected.ore),color=safeColor(f.get('color'),nodeColor(selected)),marker=markerType(f.get('marker')),visibility=f.get('visibility')||selected.visibility||'user',updated={name:gps.name,type,x:gps.x,y:gps.y,z:gps.z,ore:type==='asteroid'?(selected.ore||'Unknown'):'—',note:f.get('description')||gps.description||'Edited GPS entry.',visibility,color,marker};try{if(document.getElementById('datasetStatus').textContent==='MYSQL CONNECTED'){const response=await fetch('http://127.0.0.1:8765/api/update',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:selected.id,name:updated.name,x:updated.x,y:updated.y,z:updated.z,location_type:updated.type,description:updated.note,visibility})});const result=await response.json();if(!response.ok||result.error)throw new Error(result.error||'Could not save to MySQL')}else await saveEntityVisibility('gps',selected.id,visibility);gpsColorSettings[String(selected.id)]={...(gpsColorSettings[String(selected.id)]||{}),color,marker};if(!saveGpsColorSettings())throw new Error('Your browser could not save the GPS display settings.');Object.assign(selected,updated);document.getElementById('editModal').classList.add('hidden');select(selected.id)}catch(err){error.textContent=err.message}};
function openRegionEditor(region){editingRegion=region;document.getElementById('regionName').value=region.name;document.getElementById('regionColor').value=regionColor(region);document.getElementById('regionMarker').value=regionMarker(region);document.getElementById('regionDescription').value=region.description||'';document.getElementById('regionVisibility').value=region.visibility||'user';document.getElementById('regionError').textContent='';regionModal.classList.remove('hidden');document.getElementById('regionName').focus()}
document.getElementById('regionForm').onsubmit=async e=>{e.preventDefault();if(!editingRegion)return;const form=new FormData(e.target),name=String(form.get('name')||'').trim(),color=safeColor(form.get('color'),regionColor(editingRegion)),marker=markerType(form.get('marker')),description=String(form.get('description')||'').trim(),visibility=form.get('visibility')||'user',error=document.getElementById('regionError');if(!name){error.textContent='Region name is required.';return}try{await saveEntityVisibility('region',editingRegion.key,visibility)}catch(err){error.textContent=err.message;return}regionSettings[editingRegion.key]={...(regionSettings[editingRegion.key]||{}),name,description,color,marker};if(!saveRegionSettings()){error.textContent='Your browser could not save region details.';return}editingRegion.name=name;editingRegion.description=description;editingRegion.color=color;editingRegion.marker=marker;editingRegion.visibility=visibility;editingRegion.clusters.forEach(cluster=>cluster.region=name);regionModal.classList.add('hidden');renderSectors();renderRegionDetails(editingRegion);if(focusedCluster)document.getElementById('backToMap').textContent='← '+regionLabel(editingRegion);draw()};
function openClusterEditor(cluster){editingCluster=cluster;document.getElementById('clusterName').value=clusterLabel(cluster);document.getElementById('clusterColor').value=clusterColor(cluster);document.getElementById('clusterMarker').value=clusterMarker(cluster);document.getElementById('clusterDescription').value=cluster.description||'';document.getElementById('clusterVisibility').value=cluster.visibility||'user';document.getElementById('clusterError').textContent='';clusterModal.classList.remove('hidden');document.getElementById('clusterName').focus()}
document.getElementById('clusterForm').onsubmit=async e=>{e.preventDefault();if(!editingCluster)return;const form=new FormData(e.target),name=String(form.get('name')||'').trim(),color=safeColor(form.get('color'),clusterColor(editingCluster)),marker=markerType(form.get('marker')),description=String(form.get('description')||'').trim(),visibility=form.get('visibility')||'user',error=document.getElementById('clusterError');if(!name){error.textContent='Cluster name is required.';return}try{await saveEntityVisibility('cluster',editingCluster.name,visibility)}catch(err){error.textContent=err.message;return}clusterSettings[editingCluster.name]={...(clusterSettings[editingCluster.name]||{}),name,description,color,marker};if(!saveClusterSettings()){error.textContent='Your browser could not save cluster details.';return}editingCluster.displayName=name;editingCluster.description=description;editingCluster.color=color;editingCluster.marker=marker;editingCluster.visibility=visibility;clusterModal.classList.add('hidden');renderSectors();renderClusterDetails(editingCluster);draw()};
const MYSQL_SYNC_INTERVAL_MS=10000;
var databaseSyncInFlight=false,databaseFingerprint='';
function syncFingerprint(data){return JSON.stringify([data.entries||[],data.clusters||[]])}
function currentMapState(){return{selectedId:selected?.id,measureId:measureOrigin?.id,regionKey:focusedRegion?.key,clusterName:focusedCluster?.name,yaw,pitch,panX,panY,zoom}}
function restoreMapState(state){if(!state){selected=null;measureOrigin=null;focusedRegion=null;focusedCluster=null;yaw=-.48;pitch=.25;panX=0;panY=0;zoom=1;return}selected=state.selectedId==null?null:nodes.find(node=>node.id===state.selectedId)||null;measureOrigin=state.measureId==null?null:nodes.find(node=>node.id===state.measureId)||null;focusedCluster=state.clusterName?clusters.find(cluster=>cluster.name===state.clusterName)||null:null;focusedRegion=focusedCluster?regions.find(region=>region.clusters.includes(focusedCluster))||null:state.regionKey?regions.find(region=>region.key===state.regionKey)||null:null;yaw=state.yaw;pitch=state.pitch;panX=state.panX;panY=state.panY;zoom=state.zoom}
function refreshMapControls(){const back=document.getElementById('backToMap'),edit=document.getElementById('editRegion');document.getElementById('zoomLabel').textContent=Math.round(zoom*100)+'%';document.getElementById('zoomSlider').value=Math.round(zoom*100);if(focusedCluster){back.textContent=overviewMode==='clusters'?'← All clusters':focusedRegion?'← '+regionLabel(focusedRegion):'← Main map';back.style.display='inline-block';edit.style.display=focusedRegion&&overviewMode!=='clusters'?'inline-block':'none';return}if(focusedRegion){back.textContent='← Main map';back.style.display='inline-block';edit.style.display='inline-block';return}back.style.display='none';edit.style.display='none'}
function markDatabaseSynced(){const status=document.getElementById('datasetStatus');status.textContent='MYSQL CONNECTED';status.title='Auto-sync enabled · last checked '+new Date().toLocaleTimeString()}
async function loadDatabase(options={}){const preserve=Boolean(options.preserve),state=preserve?currentMapState():null;if(databaseSyncInFlight)return;databaseSyncInFlight=true;try{const response=await fetch('http://127.0.0.1:8765/api/data');if(!response.ok)throw new Error('Database bridge returned HTTP '+response.status);const data=await response.json();if(data.error)throw new Error(data.error);const fingerprint=syncFingerprint(data);if(preserve&&fingerprint===databaseFingerprint){markDatabaseSynced();return}if(!Array.isArray(data.entries))throw new Error('Database bridge returned invalid GPS data');nodes.splice(0,nodes.length,...data.entries.map(entry=>{const ore=entry.ore_type||'Unknown',kind=(entry.location_type||'').toLowerCase();return{id:entry.id,name:entry.name,type:normalizeCategory(kind,ore),ore,x:Number(entry.x),y:Number(entry.y),z:Number(entry.z),note:entry.description||'Imported from MySQL.',cluster:entry.cluster_name||'Unassigned',visibility:entry.visibility||'user'}}));clusters.splice(0,clusters.length,...(Array.isArray(data.clusters)?data.clusters:[]).map(cluster=>({name:cluster.name,x:Number(cluster.center_x)/1000,y:Number(cluster.center_y)/1000,z:Number(cluster.center_z)/1000,r:10,visibility:cluster.visibility||'user',regionKey:cluster.region_key||'',regionVisibility:cluster.region_visibility||'user'})));clusters.forEach(cluster=>{const distances=nodes.filter(node=>node.cluster===cluster.name).map(node=>{const point=world(node);return Math.hypot(point.x-cluster.x,point.y-cluster.y,point.z-cluster.z)});cluster.r=Math.max(8,...distances)*1.35});deriveRegions();databaseFingerprint=fingerprint;restoreMapState(state);refreshMapControls();markDatabaseSynced();renderSectors();renderList();renderCurrentPosition();if(selected)select(selected.id);else if(focusedCluster)renderClusterDetails(focusedCluster);else if(focusedRegion)renderRegionDetails(focusedRegion);else showEmptySelection();draw()}catch(error){document.getElementById('datasetStatus').textContent='MYSQL OFFLINE';document.getElementById('datasetStatus').title=error.message}finally{databaseSyncInFlight=false}}
setInterval(()=>{if(!document.hidden&&document.getElementById('datasetStatus').textContent==='MYSQL CONNECTED')loadDatabase({preserve:true})},MYSQL_SYNC_INTERVAL_MS);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&document.getElementById('datasetStatus').textContent==='MYSQL CONNECTED')loadDatabase({preserve:true})});
